//! Adaptrade Builder bonus strategies (Adaptrade Software, 2010): three daily long/short systems generated by the Builder
//! program, EasyLanguage typed out in `adaptrade systems.doc` (research drive USB HDD 1/TradeStation/Adaptrade Builder
//! (adaptrade.com)/Adaptrade Builder 1.1/; the separate `AAPL daily.doc` etc. are image copies). Results:
//! Builder-BonusStrategies.pdf PDF p.6, 9, 10 (same drive, Adaptrade Builder 1.1.0 Release). Book id `adbld`. ES 5 min needs 5-minute E-mini bars,
//! QQQQ 60 min, QM crude and EURUSD have no code on the drive: not here.
//! Fills: the vault's TradeStation daily-bar simulator (books::ajmisc::Sim). Lane K4 (titles loop, 30 Oct 2026); independent
//! check authors/titles-1030/K4w/k4_ref.py (header).
use crate::books::ajmisc::{avg_true_range, back, first_ok, highest, lowest, ord, Sim, Ty, K};
use crate::books::jkbwts::dow;
use crate::connors::{claim, dmi, rsi, ParamDef, Ctx, Params, Status, StrategyDef, Trade};

pub const BOOK: &str = "adbld";
const AAPL: &str = "adbld_aapl_daily";
const AMZN: &str = "adbld_amzn_daily";
const ES: &str = "adbld_es_daily";
/// Admitted ids (authors/titles-1030/K4w/k4_ref.py (header)).
pub const REVIEWED: &[&str] = &[AAPL, AMZN, ES];
pub fn reviewed(id: &str) -> bool { REVIEWED.contains(&id) }

macro_rules! note { ($s:expr) => { concat!($s, "Machine-generated by Adaptrade Builder and fitted to one market: the printed results are mostly in-sample. Orders are made at each close for the next bar only; while a position is open no new entry order exists. TradeStation conventions as in the vault's other TradeStation code: AvgTrueRange = simple average of true range, RateOfChange = 100 x (P / P[n] - 1), Highest and Lowest include today, DayOfWeek 0 = Sunday, RSI and ADX = Wilder, market orders fill at the open, a stop or limit already through the open fills at the open, the bar then runs open, nearer extreme, far extreme, close. Prices are not rounded to a tick (the Builder manual says Builder does not round). [Reading] Orders start at the first bar with every indicator defined inside the window. Other instruments, and India, are a declared application.") } }

pub fn catalogue() -> Vec<StrategyDef> {
    let d = |id: &'static str, name: &'static str, rules: &'static [&'static str], notes: &'static str, claim| StrategyDef { id, name, group: "Adaptrade Builder bonus strategies", session: 0, dir: "Long/Short", status: Status::Live,
        needs_volume: false, needs_vix: false, needs_series: &[], book: BOOK, rules, notes, claim };
    vec![
        d(AAPL, "Apple daily: 2-day low change sets the side, 14-bar breakout stop, ATR target, 91% trail, 78-bar exit", &[
            "F|\"EntCondL = (RateOfChange(L, N1) >= X1); EntCondS = (RateOfChange(L, N1) <= X1)\" (N1 2, X1 -3.8302)",
            "E|\"If MarketPosition = 0 and EntCondL then Buy next bar at Highest(H, NBarEn) stop\"; \"... EntCondS then Sell short next bar at Lowest(L, NBarEn) stop\" (NBarEn 14)",
            "X|\"If C - EntryPrice > ATRFrTrail * ATRTrail then LTrailOn = true\"; \"NewLStop = EntryPrice + TrailPct * (C - EntryPrice)/100; LStop = MaxList(LStop, NewLStop)\"; \"If LTrailOn then Sell next bar at LStop stop\" (ATRFrTrail 4.6394, ATRTrail = AvgTrueRange(90), TrailPct 91); short mirrored",
            "X|\"Sell next bar at EntryPrice + ATRFrTarg * ATRTarg limit\" (ATRFrTarg 2.0181, ATRTarg = AvgTrueRange(11)); short mirrored",
            "X|\"If BarsSinceEntry >= NBarEx then Sell next bar at market\" (NBarEx 78); short mirrored"],
            note!(""), claim("", "", "$37,602 on 100 shares after $25 per trade; a further $3,443 from 9/18/2009 to 3/18/2010", "", "AAPL 9/19/1994-9/17/2009 (Builder-BonusStrategies.pdf PDF p.10)")),
        d(AMZN, "Amazon daily: 0.66 ATR breakout stops both ways, 0.86 ATR target, 43-bar exit, no stop loss", &[
            "F|\"EntCondL = ((AvgTrueRange(N1) < AvgTrueRange(N2)) or (DayOfWeek(date) > N3))\"; EntCondS the same (N1 17, N2 15, N3 1)",
            "E|\"Buy next bar at H + ATRFrEn * ATR stop\"; \"Sell short next bar at L - ATRFrEn * ATR stop\" (ATRFrEn 0.6588, ATR = AvgTrueRange(47)); only while flat",
            "X|\"Sell next bar at EntryPrice + ATRFrTarg * ATR limit\" (ATRFrTarg 0.8638); short mirrored",
            "X|\"If BarsSinceEntry >= NBarEx then Sell next bar at market\" (NBarEx 43); short mirrored; the code has no stop loss"],
            note!("Both entry stops work together while flat. [Reading] If one bar reaches both, they fill in the bar's path order and the second reverses the first (Sell short closes a long), as TradeStation would. "),
            claim("", "", "$161,600 on 500 shares after $25 per trade; a further $15,960 from 5/16/1997 to 5/16/1999", "", "AMZN 5/16/1999-3/16/2010 (Builder-BonusStrategies.pdf PDF p.9)")),
        d(ES, "E-mini S&P daily: Monday pullback or ADX(15) above 23 long, RSI of the open at or below 51 short, ATR targets, 93 / 57-bar exits", &[
            "F|\"EntCondL = (((C[NL1] <= C[NL2]) and (DayOfWeek(date) < NL3)) or (ADX(NL4) > XL1))\" (NL1 2, NL2 19, NL3 2, NL4 15, XL1 23)",
            "F|\"EntCondS = ((RSI(O, NS1) <= XS1) and (DayOfWeek(date) <= NS2))\" (NS1 25, XS1 51, NS2 4)",
            "E|\"If MarketPosition = 0 and EntCondL then Buy next bar at market\"; \"If MarketPosition = 0 and EntCondS then Sell short next bar at market\"",
            "X|\"Sell next bar at EntryPrice + ATRFrTargL * ATRTargL limit\" (2.6680 x AvgTrueRange(61)); \"Buy to cover next bar at EntryPrice - ATRFrTargS * ATRTargS limit\" (1.2217 x AvgTrueRange(33))",
            "X|\"If BarsSinceEntry >= NBarExL then Sell next bar at market\" (93); \"If BarsSinceEntry >= NBarExS then Buy to cover next bar at market\" (57); no stop loss"],
            note!("[Reading] When both conditions hold on one close the code places both market orders: the buy fills and the short reverses it at the same open (a zero-P&L long is recorded), as TradeStation would; p.both = 1 takes the long alone (not what the code does). On SPY the code's reading makes $100,671 against the printed $146,763 on 2000-2010, the long-alone option $4,616. Instrument swap: built on E-mini S&P futures (not held), so the cash index and ETFs stand in. "),
            claim("", "", "$146,763 on one contract after $25 per trade; a further $28,925 from 3/17/1999 to 3/17/2000", "", "E-mini S&P 3/17/2000-3/15/2010 (Builder-BonusStrategies.pdf PDF p.6)")),
    ]
}
pub fn family_of(id: &str) -> Option<(&'static str, &'static str, &'static str)> {
    match id { AAPL => Some((AAPL, "Adaptrade Builder: Apple daily", "as generated")), AMZN => Some((AMZN, "Adaptrade Builder: Amazon daily", "as generated")), ES => Some((ES, "Adaptrade Builder: E-mini S&P daily", "as generated")), _ => None }
}
pub fn params(id: &str) -> Option<Vec<ParamDef>> {
    let p = |key, label, def, min, max, step| ParamDef { key, label, def, min, max, step };
    match id {
        AAPL => Some(vec![p("n1", "N1: bars in the change of the low", 2., 1., 20., 1.), p("x1", "X1: change threshold, %", -3.8302, -20., 20., 0.1), p("n_bar_en", "NBarEn: breakout bars", 14., 2., 100., 1.), p("n_atr_targ", "NATRTarg", 11., 2., 100., 1.), p("atr_fr_targ", "ATRFrTarg", 2.0181, 0.1, 10., 0.1), p("n_atr_trail", "NATRTrail", 90., 2., 200., 1.), p("atr_fr_trail", "ATRFrTrail", 4.6394, 0.1, 20., 0.1), p("trail_pct", "TrailPct", 91., 1., 100., 1.), p("n_bar_ex", "NBarEx", 78., 1., 300., 1.)]),
        AMZN => Some(vec![p("n1", "N1", 17., 2., 100., 1.), p("n2", "N2", 15., 2., 100., 1.), p("n3", "N3: day of week", 1., 0., 5., 1.), p("n_atr", "NATR", 47., 2., 200., 1.), p("atr_fr_en", "ATRFrEn", 0.6588, 0.01, 5., 0.05), p("atr_fr_targ", "ATRFrTarg", 0.8638, 0.05, 10., 0.05), p("n_bar_ex", "NBarEx", 43., 1., 300., 1.)]),
        ES => Some(vec![p("nl1", "NL1", 2., 0., 100., 1.), p("nl2", "NL2", 19., 0., 100., 1.), p("nl3", "NL3: day of week", 2., 0., 6., 1.), p("nl4", "NL4: ADX bars", 15., 2., 100., 1.), p("xl1", "XL1: ADX level", 23., 1., 80., 1.), p("ns1", "NS1: RSI of the open bars", 25., 2., 100., 1.), p("ns2", "NS2: day of week", 4., 0., 6., 1.), p("xs1", "XS1: RSI level", 51., 1., 99., 1.),
            p("n_atr_targ_l", "NATRTargL", 61., 2., 200., 1.), p("atr_fr_targ_l", "ATRFrTargL", 2.668, 0.1, 10., 0.1), p("n_bar_ex_l", "NBarExL", 93., 1., 300., 1.), p("n_atr_targ_s", "NATRTargS", 33., 2., 200., 1.), p("atr_fr_targ_s", "ATRFrTargS", 1.2217, 0.1, 10., 0.1), p("n_bar_ex_s", "NBarExS", 57., 1., 300., 1.),
            p("both", "Both conditions on one close: 0 = both orders fill (the code in TradeStation), 1 = long alone (not from the code)", 0., 0., 1., 1.)]),
        _ => None,
    }
}
pub fn run(id: &str, x: &Ctx, from: usize, to: usize, p: &Params) -> Option<Vec<Trade>> {
    if !reviewed(id) || from >= to || to >= x.r.len() { return None; }
    let defs = params(id)?;
    let g = |k: &str| p.get(k).copied().unwrap_or_else(|| defs.iter().find(|d| d.key == k).unwrap().def);
    let u = |k: &str| g(k).round().max(1.) as usize;
    let n = x.c.len();
    let mut s = Sim::new();
    match id {
        AAPL => {
            let nb = u("n_bar_en");
            let lb = back(&x.l, u("n1"));
            let roc: Vec<f64> = (0..n).map(|i| 100. * (x.l[i] / lb[i] - 1.)).collect();
            let (hh, ll, at, ar) = (highest(&x.h, nb), lowest(&x.l, nb), avg_true_range(x, u("n_atr_targ")), avg_true_range(x, u("n_atr_trail")));
            let (x1, ft, fr, pct, nx) = (g("x1"), g("atr_fr_targ"), g("atr_fr_trail"), g("trail_pct"), u("n_bar_ex"));
            let (mut lon, mut son, mut ls, mut ss) = (false, false, 0., 1e10_f64);
            for i in first_ok(n, from, &[&roc, &hh, &ll, &at, &ar])..to {
                let c = x.c[i];
                let mut q = vec![];
                if s.pos == 0 {
                    if roc[i] >= x1 { q.push(ord(K::Buy, Ty::Stop(hh[i]), "breakout stop")); lon = false; ls = 0.; }
                    if roc[i] <= x1 { q.push(ord(K::Short, Ty::Stop(ll[i]), "breakdown stop")); son = false; ss = 1e10; }
                } else if s.pos > 0 {
                    let e = s.ep();
                    if c - e > fr * ar[i] { lon = true; }
                    if lon { ls = f64::max(ls, e + pct * (c - e) / 100.); }
                    if s.bse(i) >= nx { q.push(ord(K::XL, Ty::Mkt, "bar limit · market")); }
                    if lon { q.push(ord(K::XL, Ty::Stop(ls), "trailing stop")); }
                    q.push(ord(K::XL, Ty::Lim(e + ft * at[i]), "ATR target"));
                } else {
                    let e = s.ep();
                    if e - c > fr * ar[i] { son = true; }
                    if son { ss = ss.min(e - pct * (e - c) / 100.); }
                    if s.bse(i) >= nx { q.push(ord(K::XS, Ty::Mkt, "bar limit · market")); }
                    if son { q.push(ord(K::XS, Ty::Stop(ss), "trailing stop")); }
                    q.push(ord(K::XS, Ty::Lim(e - ft * at[i]), "ATR target"));
                }
                s.bar(x, i + 1, &q);
            }
        }
        AMZN => {
            let (a1, a2, a) = (avg_true_range(x, u("n1")), avg_true_range(x, u("n2")), avg_true_range(x, u("n_atr")));
            let (d3, fe, ft, nx) = (g("n3") as i64, g("atr_fr_en"), g("atr_fr_targ"), u("n_bar_ex"));
            for i in first_ok(n, from, &[&a1, &a2, &a])..to {
                let mut q = vec![];
                if s.pos == 0 {
                    if a1[i] < a2[i] || dow(&x.r[i].date) > d3 {
                        q.push(ord(K::Buy, Ty::Stop(x.h[i] + fe * a[i]), "high + ATR stop"));
                        q.push(ord(K::Short, Ty::Stop(x.l[i] - fe * a[i]), "low - ATR stop"));
                    }
                } else {
                    let k = if s.pos > 0 { K::XL } else { K::XS };
                    if s.bse(i) >= nx { q.push(ord(k, Ty::Mkt, "bar limit · market")); }
                    q.push(ord(k, Ty::Lim(s.ep() + s.pos as f64 * ft * a[i]), "ATR target"));
                }
                s.bar(x, i + 1, &q);
            }
        }
        _ => {
            let (c1, c2) = (back(&x.c, g("nl1").max(0.) as usize), back(&x.c, g("nl2").max(0.) as usize));
            let (ad, r, tl, ts) = (dmi(x.r, u("nl4")).1, rsi(&x.o, u("ns1")), avg_true_range(x, u("n_atr_targ_l")), avg_true_range(x, u("n_atr_targ_s")));
            let (d3, x1, d2, x2, fl, fs, nl, ns, both) = (g("nl3") as i64, g("xl1"), g("ns2") as i64, g("xs1"), g("atr_fr_targ_l"), g("atr_fr_targ_s"), u("n_bar_ex_l"), u("n_bar_ex_s"), g("both") == 1.);
            for i in first_ok(n, from, &[&c1, &c2, &ad, &r, &tl, &ts])..to {
                let mut q = vec![];
                if s.pos == 0 {
                    let d = dow(&x.r[i].date);
                    let lg = (c1[i] <= c2[i] && d < d3) || ad[i] > x1;
                    if lg { q.push(ord(K::Buy, Ty::Mkt, "long condition · market")); }
                    if r[i] <= x2 && d <= d2 && !(lg && both) { q.push(ord(K::Short, Ty::Mkt, "short condition · market")); }
                } else if s.pos > 0 {
                    if s.bse(i) >= nl { q.push(ord(K::XL, Ty::Mkt, "bar limit · market")); }
                    q.push(ord(K::XL, Ty::Lim(s.ep() + fl * tl[i]), "ATR target"));
                } else {
                    if s.bse(i) >= ns { q.push(ord(K::XS, Ty::Mkt, "bar limit · market")); }
                    q.push(ord(K::XS, Ty::Lim(s.ep() - fs * ts[i]), "ATR target"));
                }
                s.bar(x, i + 1, &q);
            }
        }
    }
    Some(s.done(x, to))
}

